using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using FutebolDeDiscos;
public static class RuntimeHarness {
static int checks;static string caseName;
static void Check(bool condition,string message){checks++;if(!condition)throw new Exception(caseName+": "+message+" Errors: "+string.Join(" | ",Debug.Errors.ToArray()));}
static object Call(object obj,string name,params object[] args){var m=obj.GetType().GetMethod(name,BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance);if(m==null)throw new Exception("Missing method "+name);try{return m.Invoke(obj,args);}catch(TargetInvocationException e){throw e.InnerException;}}
static void Reset(){foreach(var go in GameObject.All.Where(g=>g.transform.parent==null&&!g.destroyed).ToArray())UnityEngine.Object.Destroy(go);GameObject.All.Clear();Scheduler.Reset();Time.captureDeltaTime=0;Debug.Errors.Clear();Debug.Warnings.Clear();Debug.Messages.Clear();}
static TeamData Team(string id,Color color){var t=ScriptableObject.CreateInstance<TeamData>();t.name=id;t.nomeEquipe=id.ToUpperInvariant();t.sigla=id;t.corPrincipal=color;t.corSecundaria=Color.white;t.elenco.Add(new JogadorDados{nomeJogador=id+" Player",foto512x512=new Sprite()});t.elenco.Add(new JogadorDados{nomeJogador=id+" Second"});return t;}
sealed class Match {public GameObject root;public ProjetoFutebolDiscos config;public PartidaDiscos engine;public CampoDiscos campo;public HudFutebolDiscos hud;public UniversalUI ui;public GoalBannerUI banner;public TeamData a,b;public List<JogadorDados> repsA,repsB;public GolDiscos left,right;
 public Match(){root=new GameObject("RuntimeFixture");config=root.AddComponent<ProjetoFutebolDiscos>();config.tema=ScriptableObject.CreateInstance<TemaCompeticao>();config.tema.fonteTexto=config.tema.fonteTitulo=TMPro.TMP_Settings.defaultFontAsset;ui=root.AddComponent<UniversalUI>();ui.ativarGoldenGoal=false;ui.duracaoRealEmSegundos=45;ui.tempoCongeladoPosJogo=0;banner=root.AddComponent<GoalBannerUI>();banner.tempoDeExibicao=.06f;banner.intervaloEntreBanners=0;campo=root.AddComponent<CampoDiscos>();hud=root.AddComponent<HudFutebolDiscos>();engine=root.AddComponent<PartidaDiscos>();campo.Construir(config);hud.Construir(config,ui,banner);engine.Configurar(config,campo,hud);a=Team("home",Color.blue);b=Team("away",Color.red);repsA=a.ObterTitularesDaPartida();repsB=b.ObterTitularesDaPartida();left=root.GetComponentsInChildren<GolDiscos>().Single(g=>g.esquerda);right=root.GetComponentsInChildren<GolDiscos>().Single(g=>!g.esquerda);}
 public void Prepare(){engine.PrepararPartida(a,b,repsA,repsB,a.corPrincipal,b.corPrincipal);ui.ConfigurarPartida(a,b,null,repsA,repsB);}
 public void Start(){Prepare();ui.IniciarCronometro();engine.IniciarPartida(a,b,float.MaxValue,repsA,repsB,a.corPrincipal,b.corPrincipal);}
 public void ResetAfterGoal(){Time.captureDeltaTime=.25f;for(int i=0;i<6;i++){Call(engine,"Update");Scheduler.Tick(.001f);}Time.captureDeltaTime=0;}
 public void Cross(bool leftGoal){engine.Bola.Corpo.position=new Vector2((leftGoal?-1:1)*(CampoDiscos.MeioComprimento+config.tamanhoBola*.5f+.03f),0);Call(leftGoal?left:right,"OnTriggerEnter2D",engine.Bola.GetComponent<CircleCollider2D>());}
}
static void Preparation(){caseName="preparation and stadium";var m=new Match();m.Prepare();Check(m.engine.Atletas.Count==6&&m.root.GetComponentsInChildren<BolaDiscos>().Length==1,"fixed team discs and exactly one scoring ball");Check(m.engine.Atletas.All(a=>!a.Corpo.simulated)&&!m.engine.Bola.Corpo.simulated&&!m.ui.partidaEmAndamento,"preparation stays frozen before photo opening");Check(m.engine.Atletas.All(a=>Math.Abs(a.GetComponent<CircleCollider2D>().radius-.5f)<.0001f)&&Math.Abs(m.engine.Bola.GetComponent<CircleCollider2D>().radius-.21f)<.0001f,"colliders use world diameter rather than source sprite pixel size");Check(m.engine.Atletas[0].Jogador==m.repsA[0]&&m.engine.Atletas[3].Jogador==m.repsB[0],"selected representative is captain of each physical team");Check(m.root.GetComponentsInChildren<GolDiscos>().Length==2&&m.root.GetComponentsInChildren<BoxCollider2D>().Count(c=>c.isTrigger)==2,"field has exactly two goal sensors");Check(m.root.GetComponentsInChildren<Transform>().Where(t=>t.gameObject.name=="Halfway Line").All(t=>t.GetComponent<Collider2D>()==null),"halfway line does not block white ball");Check(m.ui.placarTimeA!=null&&m.ui.textoCronometro!=null&&m.banner.painelBanner!=null,"real broadcast builds all score clock banner bindings");m.ui.IniciarCronometro();m.engine.IniciarPartida(m.a,m.b,45,m.repsA,m.repsB,m.a.corPrincipal,m.b.corPrincipal);Check(m.engine.EmAndamento&&!m.engine.EmReposicao&&m.engine.Atletas.All(a=>a.Corpo.simulated)&&m.engine.Bola.Corpo.simulated,"kickoff releases fixed actors only after UI starts");Check(Math.Abs(m.engine.Bola.Corpo.linearVelocity.x)>1,"kickoff imparts a real physical velocity");var old=m.engine.Bola;var oldActor=old.gameObject;m.Prepare();Check(oldActor.destroyed&&!oldActor.activeInHierarchy&&m.engine.Bola!=old&&m.engine.Atletas.Count==6,"new match disposes old actors before creating replacement");Check(Debug.Errors.Count==0,"setup has no integration errors");Reset();}
static void Goals(){caseName="goal recognition and restart";var m=new Match();m.Start();var ball=m.engine.Bola;var col=ball.GetComponent<CircleCollider2D>();Call(m.right,"OnTriggerEnter2D",m.engine.Atletas[0].GetComponent<CircleCollider2D>());Check(m.ui.GolsA==0&&m.ui.GolsB==0,"team disc crossing sensor cannot score");ball.Corpo.position=new Vector2(CampoDiscos.MeioComprimento+ m.config.tamanhoBola*.5f-.005f,0);Call(m.right,"OnTriggerStay2D",col);Check(m.ui.GolsA==0,"partially crossed white ball is not goal");ball.Corpo.position=new Vector2(CampoDiscos.MeioComprimento+.7f,CampoDiscos.MeioGol+.01f);Call(m.right,"OnTriggerEnter2D",col);Check(m.ui.GolsA==0,"crossing behind end line outside posts is not goal");ball.Corpo.position=new Vector2(CampoDiscos.MeioComprimento+.7f,CampoDiscos.MeioGol-m.config.tamanhoBola*.25f);Call(m.right,"OnTriggerEnter2D",col);Check(m.ui.GolsA==0,"ball whose edge overlaps a post is not fully inside goal mouth");ball.RegistrarToque(m.engine.Atletas[0]);m.Cross(false);Check(m.ui.GolsA==1&&m.ui.GolsB==0&&m.engine.EmAndamento&&m.engine.EmReposicao,"right goal scores only for home team and queues restart");Check(!ball.Corpo.simulated&&m.engine.Atletas.All(a=>!a.Corpo.simulated),"goal freezes all bodies during reset pause");Check(m.banner.TemBannersPendentes&&m.banner.textoDados.text.Contains("HOME PLAYER"),"last attacking touch identifies real scorer in original banner queue");Call(m.right,"OnTriggerStay2D",col);Call(m.right,"OnTriggerEnter2D",col);Check(m.ui.GolsA==1,"repeated trigger events during restart never duplicate goal");float before=m.ui.TempoAtual;Time.captureDeltaTime=.25f;Call(m.ui,"Update");Check(m.ui.TempoAtual==before,"regulation clock pauses while kickoff reset is pending");m.ResetAfterGoal();Check(!m.engine.EmReposicao&&ball.Corpo.simulated&&Vector2.Distance(ball.Corpo.position,Vector2.zero)<.0001f&&ball.UltimoToque==null,"restart returns same white ball to center and clears prior scorer");Check(m.engine.Atletas.All(a=>a.Corpo.simulated)&&m.ui.GolsA==1,"restart releases teams without resetting score");m.banner.LimparFila();ball.RegistrarToque(m.engine.Atletas[0]);m.Cross(true);Check(m.ui.GolsA==1&&m.ui.GolsB==1,"left goal scores away even after home player last touched ball");Check(m.banner.textoDados.text.Contains("AWAY PLAYER"),"own-goal fallback cannot credit opposing player as away scorer");m.engine.PararPartida();Call(m.left,"OnTriggerStay2D",col);Check(m.ui.GolsB==1,"stopped game ignores queued sensor callback");Reset();}
static void DrawGoldenGoal(){caseName="draws and golden goal";var m=new Match();m.Start();m.ui.duracaoRealEmSegundos=.02f;Call(m.ui,"Update");Check(!m.ui.partidaEmAndamento&&!m.engine.EmAndamento&&m.ui.GolsA==m.ui.GolsB,"league can end tied without fabricated winner");Scheduler.Tick();Check(Time.timeScale==1,"league end releases final pause normally");m.ui.ativarGoldenGoal=true;m.Start();m.ui.duracaoRealEmSegundos=.02f;Call(m.ui,"Update");Check(m.ui.EmProrrogacao&&m.ui.partidaEmAndamento&&m.engine.EmAndamento,"knockout tied regulation continues physical golden goal");m.Cross(false);Check(m.ui.GolsA==1&&!m.ui.partidaEmAndamento&&!m.engine.EmAndamento&&!m.engine.Bola.Corpo.simulated,"first real golden goal freezes and ends game");Check(m.banner.TemBannersPendentes,"golden goal queues celebration after immediate clock close");Scheduler.Tick();Check(Time.timeScale==0,"post-game coroutine waits for queued golden-goal banner");for(int i=0;i<10;i++)Scheduler.Tick(.02f);Check(!m.banner.TemBannersPendentes&&Time.timeScale==1&&!m.ui.EmProrrogacao,"golden goal ending awaits banner then releases progression");m.Cross(true);Check(m.ui.GolsB==0,"late opponent trigger cannot overwrite finished golden goal");Reset();}
static void MotionLifecycle(){caseName="movement limits and lifecycle";var m=new Match();m.Start();var a=m.engine.Atletas[0];a.Corpo.position=new Vector2(5,20);Call(m.engine,"FixedUpdate");Check(a.Corpo.position.x<=-.5f&&a.Corpo.position.y<=CampoDiscos.MeioLargura-.5f,"athlete recovery respects own-half and touchline limits");m.engine.Bola.Corpo.linearVelocity=new Vector2(1000,1000);Call(m.engine,"FixedUpdate");Check(m.engine.Bola.Corpo.linearVelocity.magnitude<=m.config.velocidadeMaximaBola+.001f,"white ball maximum speed is capped");m.engine.Bola.Corpo.position=new Vector2(100,100);Call(m.engine,"FixedUpdate");Check(Vector2.Distance(m.engine.Bola.Corpo.position,Vector2.zero)<.0001f&&m.ui.GolsA==0&&m.ui.GolsB==0,"escaped white ball resets without awarding points");m.engine.Bola.Corpo.linearVelocity=Vector2.zero;for(int i=0;i<150;i++)Call(m.engine,"FixedUpdate");Check(m.engine.Bola.Corpo.linearVelocity.magnitude>0&&m.ui.GolsA==0,"trapped ball receives bounded physical impulse without synthetic score");m.engine.enabled=false;Check(!m.engine.EmAndamento&&m.engine.Atletas.All(d=>!d.Corpo.simulated)&&!m.engine.Bola.Corpo.simulated,"disabling engine immediately freezes physics");m.engine.enabled=true;Check(!m.engine.EmAndamento,"reenabling engine does not start unrequested game");m.Start();m.ui.enabled=false;m.Cross(false);Check(m.ui.GolsA==0,"disabled score authority refuses goal callbacks");Call(m.engine,"Update");Check(!m.engine.EmAndamento&&!m.engine.Bola.Corpo.simulated,"engine stops if score/clock component becomes inactive");m.ui.enabled=true;m.Start();m.ui.CancelarPartida();Check(!m.engine.EmAndamento&&!m.ui.partidaEmAndamento,"UI cancellation synchronously stops physical engine");m.Start();var savedMaterial=m.campo.MaterialSprites;var theme=m.config.tema;var oldCanvas=m.ui.GetComponentInChildren<Canvas>();m.hud.Construir(m.config,m.ui,m.banner);Check(oldCanvas.gameObject.destroyed&&m.ui.GetComponentsInChildren<Canvas>(true).Length==1&&m.root.activeInHierarchy,"rebuilding HUD disposes retired Canvas without deactivating manager");m.campo.Limpar();Check(savedMaterial.destroyed&&!theme.destroyed&&m.campo.SpriteCirculo==null,"field cleanup destroys only its owned runtime resources");UnityEngine.Object.Destroy(m.root);Check(PartidaDiscos.Instance==null&&UniversalUI.Instance==null&&GoalBannerUI.Instance==null,"destroying match clears all runtime singletons");Reset();}
public static void Main(){string dir=Path.Combine(Path.GetTempPath(),"disc-runtime-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);Application.persistentDataPath=dir;try{Reset();Preparation();Goals();DrawGoldenGoal();MotionLifecycle();Console.WriteLine("PASS "+checks+" runtime integration assertions: scoring, complete crossing, retriggers, kickoff, draw/golden goal, physical bounds, resource ownership and lifecycle.");Console.WriteLine("All runtime project sources compiled together against Unity/TMP API facade. No Unity contacts or rendering were simulated.");}finally{Reset();Directory.Delete(dir,true);}}
}
